"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["70437"],{68131(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.nota_do_enem_sem_banca_de_importacao_das_notas","status":422,"titulo":"O processo que usa a nota do ENEM com inscri\xe7\xe3o pr\xf3pria n\xe3o prev\xea a banca de importa\xe7\xe3o das notas do INEP"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.nota_do_enem_sem_banca_de_importacao_das_notas","requisitos":["UNI-REQ-0339","UNI-REQ-0340"],"oQueAconteceu":["O processo usa a nota do ENEM com inscri\xe7\xe3o pr\xf3pria, e nenhuma fase nem etapa\\nprev\xea a banca de importa\xe7\xe3o das notas do INEP (UNI-REQ-0340). \xc9 essa banca que\\nimporta o retorno do INEP e resolve as cr\xedticas da importa\xe7\xe3o (UNI-REQ-0339).\\nSem ela, as notas n\xe3o teriam quem as importasse, e o edital n\xe3o \xe9 publicado.","A banca \xe9 reconhecida pelo papel de importar as notas do INEP, registrado na\\nbanca quando ela \xe9 criada, e n\xe3o pelo nome do tipo. O processo que n\xe3o usa a\\nnota do ENEM n\xe3o exige essa banca, e o de inscri\xe7\xe3o pr\xf3pria sem a nota do ENEM\\ntamb\xe9m n\xe3o.","A confer\xeancia \xe9 de completude e roda na publica\xe7\xe3o e na retifica\xe7\xe3o em ato\\n\xfanico. A recusa vem como o c\xf3digo desta p\xe1gina no corpo da resposta, e n\xe3o na\\nlista `errors[]`, e aponta o campo `fases` do processo, sem \xedndice."],"comoResolver":["Acrescente a banca de importa\xe7\xe3o das notas do INEP onde as notas s\xe3o importadas,\\nna fase ou na etapa. Essa banca importa; n\xe3o avalia nem julga recurso.","O painel de conformidade aponta a pend\xeancia antes da publica\xe7\xe3o, no item\\n`cronograma_nota_do_enem_com_banca_de_importacao_das_notas`."],"ondeAparece":["- Publica\xe7\xe3o inicial do processo seletivo\\n- Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);